using System.Collections.Generic;
using UnityEngine;
using PB.Logic;

namespace PB.Book
{
  /**
  *  @brief     Prove of Principle example autogenerated Book
  *  @details   The Book dosent have any valid feature but showing that\
  *             The system can jump in and out\
  *             The system can handle automated nodes\
  *             The system can deal with Commands
  */
  public class FightStoryTeller : MonoBehaviour, IBookInterface, IScriptBookInterface
  {
    [SerializeField] EventAggregator Events; /**< Handles events comming from sub book handling*/
    private TextElements _node;              /**< THe internal node element reused for every comunication*/

    /**
    *  @brief     Startpoint of the book.
    *  @details   Initialises the first node but dosen't fill it with information this will be done
    *             in the load functions calld by scripts.
    */
    void Start()
    {
      _node = ScriptableObject.CreateInstance<TextElements>();
    }

    #region IBookInterface
    /**
    *  @brief    Returns the starting node of the book
    */
    TextElements IBookInterface.GetRootNode()
    {
      return _node;
    }

    /**
    *  @brief    Update function of the node in this book
    *  @details  To get an change with only one node existing in the book it needs to be updated.
    *            The reference ID is used to decide in which way. A ide of 0 is jsut updating itself
    *            Where as the Id 1 will lead to the exit of the book
    *            \todo since it is only a POC the exit is not clean. e.g. it will not posibel to restart the book
    *  @param    referenceId The Ide to load the book
    *  @return   returns the one and only node
    */
    TextElements IBookInterface.GetNodeByRefId(string referenceId)
    {
      switch (referenceId)
      {
        case "0":
          _node.Text = "bliblibli";
          _node.JumpTos.Clear();
          break;
        case "1":
          Events.Publish(new ProcessingFinishedEvent(true));
          _node = null; // neede to get the right node from the "book" otherwise the set Answer will overwrirte it.
          break;
        default:
          break;
      }
      return _node;
    }

    #endregion

    #region IScriptBookInterface
    /**
    *  @brief    Interface to loa the book
    *  @details  creates a dummy node and send an event to start itself
    *  @param    arg the list of scripts parameters which initalises the book
    */
    void IScriptBookInterface.Load(List<string> arg)
    {
      creatFirstNode("X", 1, 2); // just a dummy
      // call Directors Load StartANewBook function
      Events.Publish(new ProcessingStartedEvent(this as IBookInterface));
    }

    /**
    *  @brief   provides information which book is loaded
    *  @return  the book name or the default type
    */
    Ttype IScriptBookInterface.GetInfo<Ttype>()
    {
      return "This book is: Fight story teler" is Ttype value ? value : default(Ttype);
    }

    /**
    *  @brief Tests if the arguments are valid
    *  @details \todo implement the Test interface
    *  @param   Interface the function to test
    *  @param   arg the lsit of arguments for the function
    *  @return always true, currently.
    */
    bool IScriptBookInterface.Test(string Interface, List<string> arg)
    {
      return true;
    }
    #endregion

    /**
    *  @brief   creats an empty node ready to be filled
    *  @return  the created node
    */
    private TextElements createEmptyNode()
    {
      TextElements node = ScriptableObject.CreateInstance<TextElements>();
      node.name = "0";
      node.Text = "";
      node.TextNumber = 0;
      node.Comands = new List<string>();
      node.JumpTos = new List<JumpTo>() { };
      return node;
    }

    /**
    *  @brief   fills the node wit dummy information
    *  @details create some tex based on the paramers\
    *           adding 3 jumps, to it self\
    *           two to show that script interpretation is working\
    *           one to exit the book
    *  @param   combatantName the name of the object to fight
    *  @param   ownHealth The helalth of the carater
    *  @param   combatantHealth health of the combatant
    */
    private void creatFirstNode(string combatantName, int ownHealth, int combatantHealth)
    {
      _node = createEmptyNode();
      _node.Text = "You are fighting Against " + combatantName + "<br> you have " + ownHealth + " Health<br> " + combatantName + " has " + combatantHealth + " health";
      _node.Comands = new List<string>() { { new string("CHANGE(ADD, 400) -> AttrMoney") } };
      JumpTo jump = new JumpTo();
      jump.text = "reduce by 4";
      jump.referenceId = "0";
      jump.conditions = new string[] { };
      jump.comands = new string[] { "CHANGE( SUB, 4) -> AttrMoney" };
      _node.JumpTos.Add(jump);
      jump.text = "reduce by 16";
      jump.referenceId = "0";
      jump.conditions = new string[] { };
      jump.comands = new string[] { "CHANGE( SUB, 16) -> AttrMoney" };
      _node.JumpTos.Add(jump);
      jump.text = "exit";
      jump.referenceId = "1";
      jump.conditions = new string[] { };
      jump.comands = new string[] { };
      _node.JumpTos.Add(jump);
    }

  }
}